import{_ as a,o as e,c as s,a2 as l}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"Generative Agents","description":"精读 Generative Agents：记忆流、反思和规划三个组件，让 Agent 在虚拟小镇中表现出可信的长期行为。","frontmatter":{"title":"Generative Agents","description":"精读 Generative Agents：记忆流、反思和规划三个组件，让 Agent 在虚拟小镇中表现出可信的长期行为。"},"headers":[],"relativePath":"papers/generative-agents.md","filePath":"papers/generative-agents.md","lastUpdated":null}'),i={name:"papers/generative-agents.md"};function t(r,n,p,o,u,g){return e(),s("div",null,[...n[0]||(n[0]=[l(`<h1 id="generative-agents" tabindex="-1">Generative Agents <a class="header-anchor" href="#generative-agents" aria-label="Permalink to &quot;Generative Agents&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Generative Agents: Interactive Simulacra of Human Behavior</li><li>作者：Joon Sung Park、Joseph C. O&#39;Brien、Carrie J. Cai、Meredith Ringel Morris、Percy Liang、Michael S. Bernstein（Stanford University、Google）</li><li>年份：2023（UIST 2023）</li><li>链接：<a href="https://arxiv.org/abs/2304.03442" target="_blank" rel="noreferrer">arXiv:2304.03442</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>给每个 Agent 配上&quot;记忆流 + 检索 + 反思 + 规划&quot;的架构，25 个 Agent 生活在一个虚拟小镇里，能够记住经历、形成观点、制定日程，并自发产生信息传播、组织聚会这样的社会行为。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>大模型可以在单次对话中扮演一个角色，但要让一个角色在很长时间里保持一致、可信的行为，会遇到几个难题：</p><ul><li>经历越来越多，不可能全部放进上下文。</li><li>只看最近发生的事，Agent 会忘记重要的过去，行为前后矛盾。</li><li>只记录原始事件，Agent 难以形成更高层的认识（比如&quot;某人是我的好朋友&quot;）。</li><li>缺乏长期计划，Agent 的行为会显得随意、短视。</li></ul><p>作者希望构建一种架构，让 Agent 能基于长期积累的经验做出可信的行为。</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>架构的核心是 <strong>记忆流（Memory Stream）</strong>：一个按时间记录 Agent 所有经历的列表，每条记忆是一段自然语言描述，带有时间戳。围绕记忆流有三个关键机制。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             感知环境（&quot;厨房里的炉子着火了&quot;）</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span> ┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> │                       记忆流 Memory Stream                    │</span></span>
<span class="line"><span> │  [观察] 08:00 在吃早餐       [观察] 09:10 和 Maria 聊天          │</span></span>
<span class="line"><span> │  [反思] Maria 对研究很投入   [计划] 下午 2 点去图书馆              │</span></span>
<span class="line"><span> └──────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>        │ 检索                  ▲ 写入反思              ▲ 写入计划</span></span>
<span class="line"><span>        ▼                       │                       │</span></span>
<span class="line"><span> ┌──────────────────┐   ┌──────────────────┐   ┌──────────────────┐</span></span>
<span class="line"><span> │ 检索 Retrieval    │   │ 反思 Reflection   │   │ 规划 Planning     │</span></span>
<span class="line"><span> │ 得分 = 时近性      │   │ 重要性累计到阈值   │   │ 先粗后细地制定     │</span></span>
<span class="line"><span> │      + 重要性      │   │ 时，总结出更高层   │   │ 一天的日程，遇到   │</span></span>
<span class="line"><span> │      + 相关性      │   │ 的认识            │   │ 新情况时调整       │</span></span>
<span class="line"><span> └──────────────────┘   └──────────────────┘   └──────────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   检索到的记忆 + 当前情境 ──▶ 大模型 ──▶ 行动 / 对话</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><ul><li><strong>检索：</strong> 每条记忆有三个分数。时近性（越新越高，随时间衰减）、重要性（写入时由模型打分，&quot;吃早餐&quot;低，&quot;分手&quot;高）、相关性（与当前情境的 Embedding 相似度）。三者加权求和，取最高的若干条放进上下文。</li><li><strong>反思：</strong> 当近期记忆的重要性累计超过阈值时，Agent 会针对近期经历提出几个高层问题，检索相关记忆并总结出结论，这些反思本身也写回记忆流，可以被继续反思，形成层次。</li><li><strong>规划：</strong> Agent 先生成一天的粗略计划，再递归分解成更细的行动。计划同样存入记忆流，遇到意外事件时 Agent 会判断是否需要调整。</li></ul><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><ul><li><strong>涌现的社会行为：</strong> 研究者只给一个 Agent 设定了&quot;想办一场情人节派对&quot;的初始意图，其他 Agent 在之后的模拟中自发传播邀请、互相约定、并在约定时间出现在派对现场。</li><li><strong>消融评估：</strong> 研究者通过&quot;采访&quot; Agent 来评估其行为可信度（询问它的计划、记忆、对他人的看法等），由人类评估者打分。完整架构的可信度最高；去掉反思、规划或记忆中的任何一项，可信度都会下降。</li><li><strong>常见错误：</strong> 检索不到相关记忆、在记忆基础上编造细节、以及受模型本身风格影响而过于礼貌、合作。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>记忆需要分层。</strong> 原始事件、提炼后的认识、计划，本质上是不同粒度的信息。这一思路直接影响了后来 Agent 记忆系统的设计，详见 <a href="/guide/08-memory/memory-types">记忆的分类</a>。</li><li><strong>检索不只看相关性。</strong> &quot;时近性 + 重要性 + 相关性&quot;的组合打分非常实用。只用向量相似度做记忆检索，往往会漏掉重要但措辞不同的信息，或者召回过时的信息。</li><li><strong>写入时就做加工。</strong> 在写入记忆时让模型打一个重要性分数，或者定期把零碎记忆总结成高层结论，比读取时再处理更高效。</li><li><strong>反思是&quot;压缩&quot;的一种形式。</strong> 把大量细节总结成少量结论，既节省上下文，又提升决策质量，与 <a href="/guide/07-context-engineering/compression">压缩与摘要</a> 的思路一致。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>成本很高：每个 Agent 每个时间步都要多次调用模型，大规模、长时间模拟代价昂贵。</li><li>评估以&quot;可信度&quot;为主，属于主观指标，不能直接说明 Agent 在任务完成类场景中的效果。</li><li>记忆会不断增长，检索和反思的质量会受到影响，论文没有充分讨论遗忘和记忆冲突。</li><li>Agent 的行为受底层模型的价值观和风格影响，表现得过于友善，与真实人类行为有差距。</li><li>研究场景是社会模拟，迁移到企业助手等任务型 Agent 时需要做较多取舍。</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/08-memory/memory-types">记忆的分类</a></li><li><a href="/guide/08-memory/long-term">长期记忆与用户画像</a></li><li><a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a></li><li><a href="/guide/07-context-engineering/compression">压缩与摘要</a></li><li><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a></li></ul>`,21)])])}const m=a(i,[["render",t]]);export{h as __pageData,m as default};
